int popcount32(uint32_t x)
{
  x = x - ((x >> 1) & 0x55555555u);
  x = (x & 0x33333333u) + ((x >> 2) & 0x33333333u);
  x = (x + (x >> 4)) & 0x0F0F0F0Fu;
  return (int)((x * 0x01010101u) >> 24);
}

void two_unique(const int *a, int n, int *x, int *y)
{
  int all = 0;
  for (int i = 0; i < n; i++) { all ^= a[i]; }       /* all = x ^ y */
  int low = all & -all;                              /* a bit where x and y differ */
  *x = 0; *y = 0;
  for (int i = 0; i < n; i++) {
    if (a[i] & low) { *x ^= a[i]; } else { *y ^= a[i]; }
  }
}

