#include <limits.h>
int divide(int dividend, int divisor)              /* divisor != 0 */
{
  if (dividend == INT_MIN && divisor == -1) { return INT_MAX; }   /* overflow */
  int negative = (dividend < 0) != (divisor < 0);
  uint64_t a = dividend < 0 ? -(int64_t)dividend : dividend;
  uint64_t b = divisor  < 0 ? -(int64_t)divisor  : divisor;
  uint64_t q = 0;
  for (int i = 31; i >= 0; i--) {
    if ((a >> i) >= b) {
      a -= b << i;
      q |= (uint64_t)1 << i;
    }
  }
  return negative ? -(int)q : (int)q;
}

