}

int integer_replacement(uint32_t n)
{
  uint64_t x = n;                 /* 64 bit: n + 1 may overflow 32 bits */
  int steps = 0;
  while (x != 1) {
    if ((x & 1) == 0)            { x >>= 1; }
    else if (x == 3 || (x & 3) == 1) { x--; }
    else                          { x++; }
    steps++;
  }
  return steps;
}

