void find_missing_repeating(const int *a, int n, int *missing, int *repeating)
{
  int x = 0;
  for (int i = 0; i < n; i++) { x ^= a[i] ^ (i + 1); }      /* missing ^ repeating */
  int low = x & -x;
  int p = 0, q = 0;
  for (int i = 0; i < n; i++) {
    if (a[i] & low)   { p ^= a[i]; } else { q ^= a[i]; }
    if ((i + 1) & low) { p ^= i + 1; } else { q ^= i + 1; }
  }
  int count = 0;
  for (int i = 0; i < n; i++) { if (a[i] == p) { count++; } }
  if (count == 2) { *repeating = p; *missing = q; }
  else            { *repeating = q; *missing = p; }
}

#include <string.h>
int max_product_of_lengths(const char *const *w, int n)
{
  uint32_t mask[1000] = {0};                     /* n <= 1000 in this sketch */
  int len[1000];
  for (int i = 0; i < n; i++) {
    len[i] = (int)strlen(w[i]);
    for (const char *p = w[i]; *p; p++) { mask[i] |= 1u << (*p - 'a'); }
  }
  int best = 0;
  for (int i = 0; i < n; i++)
    for (int j = i + 1; j < n; j++)
      if ((mask[i] & mask[j]) == 0 && len[i] * len[j] > best) { best = len[i] * len[j]; }
  return best;
}

