bool has_all_codes(const char *s, int k)           /* 1 <= k <= 20 */
{
  size_t n = strlen(s);
  uint32_t total = 1u << k;
  if (n < (size_t)k + total - 1u) { return false; }    /* not enough windows */
  uint8_t *seen = calloc(total, 1);
  uint32_t x = 0, mask = total - 1u, count = 0;
  for (size_t i = 0; i < n; i++) {
    x = ((x << 1) | (uint32_t)(s[i] - '0')) & mask;
    if (i + 1 >= (size_t)k && !seen[x]) { seen[x] = 1; count++; }
  }
  free(seen);
  return count == total;
}

int find_duplicate(const int *a, int n_plus_1)
{
  int n = n_plus_1 - 1;
  int ans = 0;
  for (int b = 0; b < 31; b++) {
    int mask = 1 << b, in_array = 0, in_range = 0;
    for (int i = 0; i < n_plus_1; i++) { if (a[i] & mask) { in_array++; } }
    for (int v = 1; v <= n; v++)       { if (v & mask)    { in_range++; } }
    if (in_array > in_range) { ans |= mask; }
  }
  return ans;
}

extern uint32_t _sidata, _sdata, _edata, _sbss, _ebss;

void Reset_Handler(void) {
    /* copy .data: Flash (LMA) -> RAM (VMA) */
    uint32_t *src = &_sidata;
    uint32_t *dst = &_sdata;
    while (dst < &_edata)
        *dst++ = *src++;

    /* zero .bss */
    for (dst = &_sbss; dst < &_ebss; dst++)
        *dst = 0;

    SystemInit();   /* clocks, optional */
    main();
    while (1) {}
}

typedef struct block {
